    out = [row[:] for row in grid]

    # Markers encode a small solid square patch. Paint matching all-1
    # squares throughout the grid; the marker's color selects the paint.
    for color in (2, 3, 4, 6, 8):
        markers = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color]
        if not markers:
            continue

        # Use 3x3 when the marked cell is surrounded by a 3x3 region
        # of the underlying figure; otherwise the patch is 2x2.
        r, c = markers[0]
        size = 2
        for n in (3, 2):
            if (r-n//2 >= 0 and c-n//2 >= 0 and
                r-n//2+n <= h and c-n//2+n <= w and
                all(grid[y][x] in (1, color)
                    for y in range(r-n//2, r-n//2+n)
                    for x in range(c-n//2, c-n//2+n))):
                size = n
                break

        # Paint every occurrence of the underlying solid patch.
        for y in range(h-size+1):
            for x in range(w-size+1):
                if all(grid[yy][xx] == 1
                       for yy in range(y, y+size)
                       for xx in range(x, x+size)):
                    for yy in range(y, y+size):
                        for xx in range(x, x+size):
                            out[yy][xx] = color

        # Keep marker pixels unchanged.
        for y, x in markers:
            out[y][x] = color
    return out
